package org.firstinspires.ftc.teamcode.opmodes.auto.generated;

import com.pedropathing.api.Paths;
import com.pedropathing.api.PoseFactory;
import com.pedropathing.ivy.Command;
import com.pedropathing.math.Pose;
import com.pedropathing.paths.Path;

import org.firstinspires.ftc.teamcode.autokit.AutoKit;
import org.firstinspires.ftc.teamcode.autokit.AutoOption;

/**
 * Generated by the Auto Builder from r-3tip-b.pp. Do not edit: change the .pp and export again.
 */
public final class R3TipBAuto {

    private R3TipBAuto() {}

    /** The .pp file this was generated from. */
    public static final String SOURCE = "r-3tip-b.pp";

    /** When the .pp was saved, Michigan time (empty if unknown); the OpMode's name on the Driver Station ends with it. */
    public static final String SAVED = "11-04|7:00AM";

    /** Registered robot commands this Auto uses; checked when the OpMode initialises. */
    public static final String[] COMMANDS = {"LaunchAll", "PickFlower", "SpinUp"};

    /** Registered robot triggers this Auto uses; checked when the OpMode initialises. */
    public static final String[] TRIGGERS = {"Tip"};

    /** The alliance the Auto was drawn for ("RED" or "BLUE"); the other alliance runs it rotated half a turn about the field centre. */
    public static final String DRAWN_FOR = "RED";

    /** What the drive team may change during INIT, on gamepad 1's D-pad; nothing changed, the Auto runs as drawn. */
    public static final AutoOption[] OPTIONS = {};

    /** Where the robot starts, for the given alliance. */
    public static Pose startPose(boolean rotated) {
        return poses(rotated).of(55.6, 7.7, 90);
    }

    private static PoseFactory poses(boolean rotated) {
        return rotated ? PoseFactory.degrees().mirrorAroundPoint(70.75, 70.75) : PoseFactory.degrees();
    }

    /** Builds the whole Auto. Call once, at init; schedule the result at start. */
    public static Command build(AutoKit kit, boolean rotated) {
        PoseFactory p = poses(rotated);

        // Named points (x, y in inches, heading in degrees, Pedro field frame).
        Pose rightStart = p.of(55.6, 7.7, 90);
        Pose wallFlowerStaging = p.of(23.1, 47.2, 180);
        Pose leftLaunchOffset = p.of(41, 121.5, 296.4);
        Pose scoringFlowerStaging = p.of(47.2, 119.3, 90);
        Pose rightLaunchOffset = p.of(41, 20, 68.7);

        // Other poses the paths need (control points, unnamed endpoints).
        Pose wallLaneToLeftLaunchOffsetControl1 = p.of(33, 120, 0);
        Pose wallLaneToRightLaunchOffsetControl1 = p.of(30, 100, 0);
        Pose wallLaneToRightLaunchOffsetControl2 = p.of(28, 45, 0);

        // Paths, written as the stock Visualizer export writes them.
        Path toWallFlowerStaging = Paths.line(rightStart, wallFlowerStaging).linear(rightStart, wallFlowerStaging);
        Path wallLaneToLeftLaunchOffset = Paths.curve(wallFlowerStaging, wallLaneToLeftLaunchOffsetControl1, leftLaunchOffset).linear(wallFlowerStaging, leftLaunchOffset);
        Path toScoringFlowerStaging = Paths.line(leftLaunchOffset, scoringFlowerStaging).linear(leftLaunchOffset, scoringFlowerStaging);
        Path wallLaneToRightLaunchOffset = Paths.curve(scoringFlowerStaging, wallLaneToRightLaunchOffsetControl1, wallLaneToRightLaunchOffsetControl2, rightLaunchOffset).linear(scoringFlowerStaging, rightLaunchOffset);
        Path toScoringFlowerStagingPath = Paths.line(leftLaunchOffset, scoringFlowerStaging).linear(leftLaunchOffset, scoringFlowerStaging);
        Path backToLeftLaunchOffset = Paths.line(scoringFlowerStaging, leftLaunchOffset).linear(scoringFlowerStaging, leftLaunchOffset);

        return kit.sequence(
                kit.command("SpinUp"),
                kit.command("LaunchAll"),
                kit.path("to WALL_FLOWER_STAGING", toWallFlowerStaging, 2.1),
                kit.command("PickFlower", 8),
                kit.path("wall lane to LEFT_LAUNCH_OFFSET", wallLaneToLeftLaunchOffset, 2.6),
                kit.command("LaunchAll"),
                kit.firstOf("Did TIP 2 come?",
                        kit.when("Tip").then(
                                kit.path("to SCORING_FLOWER_STAGING", toScoringFlowerStaging, 1.1),
                                kit.command("PickFlower", 8),
                                kit.path("wall lane to RIGHT_LAUNCH_OFFSET", wallLaneToRightLaunchOffset, 3.1),
                                kit.command("LaunchAll")),
                        kit.afterMs(2500).then(
                                kit.path("to SCORING_FLOWER_STAGING ", toScoringFlowerStagingPath, 1.1),
                                kit.command("PickFlower", 8),
                                kit.path("back to LEFT_LAUNCH_OFFSET", backToLeftLaunchOffset, 1.1),
                                kit.command("LaunchAll"))));
    }
}
